class Surface : Panel {
 public Surface(){DoubleBuffered=true;BackColor=Color.FromArgb(27,31,40);Padding=new Padding(20);Margin=new Padding(7);}
 protected override void OnPaintBackground(PaintEventArgs e){Control parent=Parent;while(parent!=null && parent.BackColor.A<255)parent=parent.Parent;e.Graphics.Clear(parent==null?Color.FromArgb(17,21,29):parent.BackColor);if(Width<32 || Height<32)return;e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var shape=Shape(new Rectangle(0,0,Width-1,Height-1),16))using(var brush=new SolidBrush(BackColor))e.Graphics.FillPath(brush,shape);}
 internal static GraphicsPath Shape(Rectangle r,int radius){int d=radius*2;var p=new GraphicsPath();p.AddArc(r.Left,r.Top,d,d,180,90);p.AddArc(r.Right-d,r.Top,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.Left,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
}
class SoftButton : Button {
