}
class AlbumView : Control {
 public Image Cover;
 public AlbumView(){DoubleBuffered=true;}
 protected override void OnPaint(PaintEventArgs e){if(Width<32 || Height<32)return;e.Graphics.Clear(Parent==null?Color.FromArgb(27,31,40):Color.FromArgb(27,31,40));e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var shape=Surface.Shape(new Rectangle(0,0,Width-1,Height-1),14)){var state=e.Graphics.Save();e.Graphics.SetClip(shape);if(Cover!=null)e.Graphics.DrawImage(Cover,ClientRectangle);else{using(var brush=new SolidBrush(Color.FromArgb(32,43,48)))e.Graphics.FillRectangle(brush,ClientRectangle);Brand.Draw(e.Graphics,ClientRectangle);}e.Graphics.Restore(state);}}
 protected override void Dispose(bool disposing){if(disposing && Cover!=null)Cover.Dispose();base.Dispose(disposing);}
}
