 internal void VerifyQueueActions(Action<bool,string> check){
  Navigate(true,false);e.S.orders.Clear();
  var played=new Order{id="ui-played",status="done",played=true,uri="spotify:track:4uLU6hMCjMI75M1A2tKUQC"};
  var waiting=new Order{id="ui-waiting",status="pending",uri=played.uri};var accepted=new Order{id="ui-accepted",status="done",uri=played.uri};
  e.S.orders.AddRange(new[]{played,waiting,accepted});RefreshView();Application.DoEvents();
  check(orders.CheckBoxes && orders.MultiSelect,"queue supports checked and selected rows");
  orders.Items.Cast<ListViewItem>().Single(row=>row.Tag==waiting).Checked=true;RefreshView();RefreshView();
  check(orders.CheckedItems.Count==1 && ((Order)orders.CheckedItems[0].Tag).id==waiting.id,"checked tracks survive repeated live refresh");
  Descendants(dashboardHost).OfType<Button>().Single(button=>button.Text==L.T("Скрыть выбранные")).PerformClick();
  check(waiting.historyHidden && waiting.status=="pending" && orders.Items.Count==2,"hide button hides checked row without cancelling request");
  Descendants(dashboardHost).OfType<Button>().Single(button=>button.Text==L.T("Очистить сыгранные")).PerformClick();
  check(played.historyHidden && !accepted.historyHidden && orders.Items.Count==1,"clear button hides played row and retains unplayed accepted row");
  orders.Items[0].Selected=true;Descendants(dashboardHost).OfType<Button>().Single(button=>button.Text==L.T("Скрыть выбранные")).PerformClick();
  check(accepted.historyHidden && orders.Items.Count==0,"hide button also supports selected row without checkbox");
  e.S.orders.Clear();checkedOrderIds.Clear();e.Save();RefreshView();Navigate(false,false);
 }
