 async void ChangeRequestSound(bool reset){
  if(soundImporting)return;
  try {
   if(reset)e.ResetRequestSound();
   else using(var dialog=new OpenFileDialog{Title=L.T("Выберите звук уведомления"),Filter="Audio (*.mp3;*.m4a;*.aac;*.flac;*.wma;*.wav;*.aif;*.aiff;*.ogg;*.opus)|*.mp3;*.m4a;*.aac;*.flac;*.wma;*.wav;*.aif;*.aiff;*.ogg;*.opus|All files (*.*)|*.*",CheckFileExists=true,Multiselect=false,RestoreDirectory=true}){
    if(dialog.ShowDialog(this)!=DialogResult.OK)return;string file=dialog.FileName;soundImporting=true;requestSoundFileLabel.Text=L.T("Подготовка сигнала…");await Task.Run(()=>e.SetRequestSound(file));
   }
  }catch(Exception ex){if(!IsDisposed)MessageBox.Show(this,L.T("Не удалось выбрать сигнал: ")+ex.Message,"TrackBridge",MessageBoxButtons.OK,MessageBoxIcon.Information);}
  finally{soundImporting=false;if(!IsDisposed)RefreshView();}
