  timeLine.Text=Clock(e.TrackProgress)+" / "+Clock(e.TrackDuration);trackMeter.Value=e.TrackDuration>0?(double)e.TrackProgress/e.TrackDuration:0;trackMeter.Invalidate();
  ruleLimit.Text=(e.S.maxTrackMinutes==0?L.T("Без лимита"):e.S.maxTrackMinutes+L.T(" мин"));ruleExplicit.Text=L.T(e.S.blockExplicit?"Запрещён":"Разрешён");ruleTracks.Text=Lines(e.S.blockedTracks).ToString();ruleArtists.Text=Lines(e.S.blockedArtists).ToString();lock(e.Gate)queueCount.Text=e.S.orders.Count(o=>o.status!="done" && o.status!="canceled").ToString();manualSkip.Enabled=running!=null && e.Chat!=null;resetVotes.Enabled=manualSkip.Enabled;
  if(coverUrl!=e.TrackImage){coverUrl=e.TrackImage;LoadCover(coverUrl);}
 }
 async void LoadCover(string url){
  int request=++coverRequest;if(album.Cover!=null){album.Cover.Dispose();album.Cover=null;album.Invalidate();}
  Uri uri;if(!Uri.TryCreate(url,UriKind.Absolute,out uri) || uri.Scheme!="https" || uri.Host!="i.scdn.co" || !uri.IsDefaultPort || uri.UserInfo!="")return;
  try{using(var response=await covers.GetAsync(uri,HttpCompletionOption.ResponseHeadersRead)){response.EnsureSuccessStatusCode();if(response.Content.Headers.ContentLength>2*1024*1024)return;using(var stream=await response.Content.ReadAsStreamAsync())using(var bytes=new MemoryStream()){var buffer=new byte[8192];int read;while((read=await stream.ReadAsync(buffer,0,buffer.Length))>0){if(bytes.Length+read>2*1024*1024)return;bytes.Write(buffer,0,read);}bytes.Position=0;using(var image=Image.FromStream(bytes)){if(image.Width>3000 || image.Height>3000)return;var copy=new Bitmap(image);if(IsDisposed || request!=coverRequest){copy.Dispose();return;}album.Cover=copy;album.Invalidate();}}}}catch(Exception){/* Keep the local artwork placeholder if the cover is unavailable. */}
 }
}
